import{_ as t,C as s,c as n,o as r,a3 as o,G as i}from"./chunks/framework.Dokpd4od.js";const y=JSON.parse('{"title":"Work with several companies","description":"","frontmatter":{},"headers":[],"relativePath":"master/general-settings/companies/multi-company.md","filePath":"master/general-settings/companies/multi-company.md","lastUpdated":1792041590000}'),c={name:"master/general-settings/companies/multi-company.md"};function l(h,e,m,p,u,d){const a=s("ImagePopup");return r(),n("div",null,[e[0]||(e[0]=o('<h1 id="work-with-several-companies" tabindex="-1">Work with several companies <a class="header-anchor" href="#work-with-several-companies" aria-label="Permalink to &quot;Work with several companies&quot;">​</a></h1><p>If you work for more than one company, Aureus lets you switch between them without signing out. The <strong>company switcher</strong> in the top bar shows which company you are working in, and lets you view records of several companies at once.</p><blockquote><p><strong>In simple words:</strong> The company switcher tells Aureus which company you are working for right now.</p></blockquote><h2 id="who-sees-the-switcher" tabindex="-1">Who sees the switcher <a class="header-anchor" href="#who-sees-the-switcher" aria-label="Permalink to &quot;Who sees the switcher&quot;">​</a></h2><p>The switcher shows in the top bar only when you are allowed to use more than one company. If you have one company, you do not see it.</p><p>An administrator sets the companies for each user in the user form, under <strong>Multi Company</strong>:</p><ul><li><strong><em>Allowed Companies:</em></strong> The companies the user may work in.</li><li><strong><em>Default Company:</em></strong> The company the user starts in. It must be one of the allowed companies.</li></ul><p>See <a href="./../users/users.html">Users</a> and <a href="./companies.html">Companies</a>.</p><h2 id="switch-company" tabindex="-1">Switch company <a class="header-anchor" href="#switch-company" aria-label="Permalink to &quot;Switch company&quot;">​</a></h2><ol><li>Click the company name in the top bar.</li><li>Click the name of the company you want.</li></ol><p>The page reloads in that company. The company in <strong>bold</strong> is the one you are working in.</p>',11)),i(a,{src:"/images1/general-settings/company_switcher.png",alt:"Top bar company switcher open with the list of companies, tick boxes, Confirm and Reset"}),e[1]||(e[1]=o('<h2 id="work-in-several-companies-at-once" tabindex="-1">Work in several companies at once <a class="header-anchor" href="#work-in-several-companies-at-once" aria-label="Permalink to &quot;Work in several companies at once&quot;">​</a></h2><ol><li>Click the company name in the top bar.</li><li>Tick the boxes of all the companies you want to see.</li><li>Click <strong>Confirm</strong>.</li></ol><p>Lists now show records from all the ticked companies. The company in bold is the current company. New records you create belong to the current company.</p><p>To go back to one company, click the name of that company, or click <strong>Reset</strong>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Click <strong>Reset</strong> to clear your choice and return to your default company.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./companies.html">Companies</a></li><li><a href="./../users/users.html">Users</a></li></ul>',7))])}const g=t(c,[["render",l]]);export{y as __pageData,g as default};
